      if (estimate.breakdown.finishesCents) appendPriceBreakdownRow(composition, "Cor global", "+" + formatCurrency(estimate.breakdown.finishesCents), selectedFrontFinishLabel() + " aplicada aos mÃ³dulos elegÃ­veis.");
      if (estimate.breakdown.handlesCents) appendPriceBreakdownRow(composition, "Puxador global", "+" + formatCurrency(estimate.breakdown.handlesCents), selectedHandle().label + " rateado nas frentes dos mÃ³dulos incluÃ­dos.");
      if (estimate.breakdown.localCents) appendPriceBreakdownRow(composition, "Pedra cooktop", "+" + formatCurrency(estimate.breakdown.localCents), "Inclusa no MÃ³dulo 02.");
      estimate.global.items.filter((item) => item.cents).forEach((item) => {
        appendPriceBreakdownRow(composition, globalItemLabel(item.id), "+" + formatCurrency(item.cents), "Impacto global aplicado uma Ãºnica vez Ã  composiÃ§Ã£o.");
      });
      const disclaimer = document.createElement("p");
